import fs from 'node:fs/promises';
const model = (await fs.readFile(new URL('../src/model.js', import.meta.url), 'utf8')).replace(/^export /gm, '');
const backend = await fs.readFile(new URL('../gas/backend.js', import.meta.url), 'utf8');
await fs.writeFile(new URL('../gas-doPost.gs', import.meta.url),
  '// Generated by npm run build:gas. Edit src/model.js and gas/backend.js.\n' + model + '\n' + backend);
